td, th {
    border: 1px solid #ccc;
    padding: 5px;
    min-width: 80px;
    text-align: left;
    cursor: text;
    box-sizing: border-box; /* Asegura que el padding no rompa los bordes */
}

/* Encabezado de filas (A, B, C...) */
thead th {
    background-color: #f0f0f0;
    font-weight: bold;
}

