function conectar() {
    const spreadsheetGrid = document.getElementById('spreadsheet-grid');
    const colorPicker = document.getElementById('colorPicker');
    const clearColorButton = document.getElementById('clearColorButton');


    if (!spreadsheetGrid) return;

    /**
     * Maneja el cambio de contenido al perder foco (blur) o presionar Enter.
     * @param {Event} event El evento que disparó la acción (focusout/keydown).
     */
    function handleCellChange(event) {
        const target = event.target;

        // 1. Determinar coordenadas y valor de contenido
        const coords = getCoordinatesFromElement(target);
        if (!coords) return;

        let newValue = '';
        let isColorChange = false;

        // Si es un blur o Enter, el valor está en textContent (o innerText).
        if (event.type === 'blur' || (event.type === 'keydown' && event.key === 'Enter')) {
            newValue = target.textContent;
        }

        if (newValue !== undefined) {
            const col = coords.col;
            const row = coords.row;

            // 2. Lógica: Actualizar estado (contenido textual)
            updateCell(col, row, newValue);

            // 3. Guardar y Renderizar
            guardar();
            render();
        }
    }

    // --- EVENT LISTENERS PARA CONTENIDO TEXTUAL ---
    spreadsheetGrid.addEventListener('blur', handleCellChange);
    spreadsheetGrid.addEventListener('keydown', function(event) {
        const target = event.target;
        if (target.hasAttribute('contenteditable') && target.textContent !== undefined) {
            // Solo procesar si se presionó Enter, que implica finalización de la edición
            if (event.key === 'Enter') {
                handleCellChange(event);
                // Prevenir el comportamiento por defecto del formulario/input al presionar enter
                event.preventDefault(); 
            }
        }
    });

    // --- EVENT LISTENERS PARA COLOR DE FONDO ---
    colorPicker.addEventListener('input', function() {
        const target = document.activeElement;
        if (target && target.hasAttribute('contenteditable') && getCoordinatesFromElement(target)) {
            const coords = getCoordinatesFromElement(target);
            const col = coords.col;
            const row = coords.row;
            const color = this.value;

            // 1. Actualizar estado de color (no es un cambio de contenido, por eso el flag)
            updateCell(col, row, color, true);

            // 2. Guardar y Renderizar para aplicar el estilo inmediatamente
            guardar();
            render();
        }
    });

    clearColorButton.addEventListener('click', function() {
        const target = document.activeElement;
        if (target && target.hasAttribute('contenteditable') && getCoordinatesFromElement(target)) {
            const coords = getCoordinatesFromElement(target);
            const col = coords.col;
            const row = coords.row;
            const defaultColor = '#ffffff';

            // 1. Actualizar estado de color a blanco (flag true)
            updateCell(col, row, defaultColor, true);

            // 2. Guardar y Renderizar para limpiar el estilo
            guardar();
            render();
        }
    });
}
