function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            let loadedState = JSON.parse(s);
            // Migración de datos: Si el estado no tiene la estructura de objeto {value, color}, lo convertimos.
            estado = {};
            for (const key in loadedState) {
                const item = loadedState[key];
                if (typeof item === 'string') {
                    // Formato antiguo (solo valor): Asumir fondo blanco y guardar el valor
                    estado[key] = { value: item, color: '#ffffff' };
                } else if (typeof item === 'object' && item !== null) {
                    // Formato nuevo o correcto
                    estado[key] = item;
                }
            }
        }
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    }
}
