function guardar() { 
    try { 
        // Aseguramos que todos los valores en el estado sean objetos con estructura {value, color} antes de guardarlos.
        const stateToSave = {};
        for (const key in estado) {
            const item = estado[key];
            if (typeof item === 'string') {
                // Esto no debería pasar si updateCell y aplicarColor funcionan correctamente, 
                // pero es un fallback para asegurar el formato de objeto.
                stateToSave[key] = { value: item || '', color: '#ffffff' };
            } else if (typeof item === 'object' && item !== null) {
                 // Asegurar que los campos existan, incluso si están vacíos o mal definidos.
                const val = item.value === undefined ? '' : String(item.value);
                const col = key.split('_')[0];
                if (!col) continue; // Skip invalid keys

                stateToSave[key] = { 
                    value: val, 
                    color: item.color || '#ffffff' 
                };
            } else {
                 // Si por alguna razón el valor no es objeto ni string (ej. undefined), lo ignoramos o default.
                 stateToSave[key] = { value: '', color: '#ffffff' };
            }
        }
        localStorage.setItem(CLAVE, JSON.stringify(stateToSave)); 
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    } 
}
