function deleteColumn(colLetter) {
    if (!selectedColumn || selectedColumn !== colLetter) return;

    // 1. Remover el encabezado de la columna
    const headerElement = document.querySelector(`#spreadsheet-grid thead tr th:contains("${colLetter}")`);
    if (headerElement) {
        headerElement.remove();
    } else {
        console.warn(`No se encontró el encabezado para la columna ${colLetter}`);
        return;
    }

    // 2. Eliminar las celdas de todas las filas del cuerpo
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    for (const row of rows) {
        // Buscar la celda correspondiente a esta columna en la fila actual.
        // Asumimos que la posición relativa se mantiene, aunque es frágil.
        let cellToRemove = null;
        if (colLetter === 'A') {
            cellToRemove = row.querySelector('[data-cell*="A,"]');
        } else if (colLetter === 'B') {
             // Esta lógica sería demasiado compleja para ser robusta sin un índice de columna real en el DOM.
             // Nos basaremos en la eliminación por patrón si es posible, pero dado que los data-cell son clave:
            const cells = Array.from(row.querySelectorAll('td'));
            for (let i = 0; i < cells.length; i++) {
                if (cells[i].getAttribute('data-cell') && cells[i].getAttribute('data-cell').includes(`${colLetter},`)) {
                    cellToRemove = cells[i];
                    break;
                }
            }
        }

        // Usaremos un selector más directo que debe funcionar si el DOM está intacto.
        const specificCellSelector = `td[data-cell*="${colLetter}_"]`;
        cellToRemove = row.querySelector(specificCellSelector);
        if (cellToRemove) {
            cellToRemove.remove();
        }
    }

    // 3. Limpiar el estado de datos para esta columna
    for (let r = 1; r <= 20; r++) {
        const key = `${colLetter}_${r}`;
        delete estado[key];
    }

    selectedColumn = null;
    guardar();
    render(); // Redibujamos para asegurar que los cambios se reflejen.
}
