function updateCell(col, row, value) {
    const key = `${col}_${row}`;
    // Solo actualizamos si el valor es diferente al que ya está guardado para evitar llamadas innecesarias a render/guard
    if (estado[key] !== String(value)) {
        estado[key] = String(value);
