function getCoordinatesFromElement(element) {
    const dataCell = element.getAttribute('data-cell');
    if (!dataCell) return null;

    // El formato en el HTML es (A, 1). Necesitamos parsearlo.
    const match = dataCell.match(/\(([^,]+),\s*(\d+)\)/);
