function conectar() {
    const spreadsheetGrid = document.getElementById('spreadsheet-grid');
    const columnHeaders = document.querySelectorAll('#spreadsheet-grid thead th[data-column]');
    const controlsDiv = document.getElementById('column-controls');

    if (!spreadsheetGrid) return;

    // --- 1. Event Listeners para selección de columna (Column Headers) ---
    // Aseguramos que los encabezados tengan un data attribute para identificar la columna fácilmente
    document.querySelectorAll('#spreadsheet-grid thead th:not(:first-child)').forEach(th => {
        const colLetter = th.textContent.trim();
        if (colLetter) {
            th.setAttribute('data-column', colLetter);
            th.style.cursor = 'pointer'; // Indica que es seleccionable
            th.addEventListener('click', function() {
                selectColumn(colLetter);
            });
        }
    });


    /**
     * Maneja el cambio de contenido al perder foco (blur) o presionar Enter.
     * @param {Event} event El evento que disparó la acción (focusout/keydown).
     */
    function handleCellChange(event) {
        const target = event.target;

        // 1. Determinar coordenadas y valor
        const coords = getCoordinatesFromElement(target);
        if (!coords) return;

        let newValue = '';

        // Si es un blur o Enter, el valor está en innerText (o value si fuera input).
        if (event.type === 'blur') {
            newValue = target.textContent;
        } else if (event.type === 'keydown' && event.key === 'Enter') {
             // Capturamos el contenido actual del elemento editable.
            newValue = target.textContent; 
        }

        if (newValue !== undefined) {
            const col = coords.col;
            const row = coords.row;

            // 2. Lógica: Actualizar estado
            updateCell(col, row, newValue);

            // 3. Guardar y Renderizar
            guardar();
            render();
        }
    }

    // Escuchamos en el contenedor principal (spreadsheet-grid) para capturar eventos de los hijos contenteditable.
    spreadsheetGrid.addEventListener('blur', handleCellChange);
    spreadsheetGrid.addEventListener('keydown', function(event) {
        const target = event.target;
        if (target.hasAttribute('contenteditable') && target.textContent !== undefined) {
            // Solo procesar si se presionó Enter, que implica finalización de la edición
            if (event.key === 'Enter') {
                handleCellChange(event);
                // Prevenir el comportamiento por defecto del formulario/input al presionar enter
                event.preventDefault(); 
            }
        }
    });

    // --- 2. Event Listeners para Controles de Columna ---
    const deleteBtn = document.getElementById('delete-column-btn');
    const colorPicker = document.getElementById('color-picker');
    const applyColorBtn = document.getElementById('apply-color-btn');
    const clearContentBtn = document.getElementById('clear-content-btn');

    // Listener para borrar columna
    if (deleteBtn) {
        deleteBtn.addEventListener('click', () => {
            const col = estado.selectedColumn;
            if (col) deleteColumn(col);
        });
    }

    // Listener para aplicar color
    if (applyColorBtn && colorPicker) {
        applyColorBtn.addEventListener('click', () => {
            const col = estado.selectedColumn;
            const color = colorPicker.value;
            if (col) applyColumnColor(col, color);
        });
    }

    // Listener para vaciar contenido
    if (clearContentBtn) {
        clearContentBtn.addEventListener('click', () => {
            const col = estado.selectedColumn;
            if (col) clearColumnContent(col);
        });
    }
}
