/**
 * Establece la columna seleccionada y muestra los controles de acción en el thead.
 * @param {string} colColLetter Letra de la columna (A, B...).
 */
function selectColumn(colColLetter) {
    // 1. Actualizar estado global para saber qué columna está activa
    estado['selectedColumn'] = colColLetter;

    // 2. Ocultar todos los botones de control primero
    document.querySelectorAll('.control-button').forEach(el => el.classList.add('hidden'));

    // 3. Mostrar solo el botón correspondiente a la columna seleccionada
    const buttonId = `col-${colColLetter}`;
    const targetButton = document.getElementById(buttonId);

    if (targetButton) {
        targetButton.classList.remove('hidden');
        // Re-establecer el texto para indicar qué columna se está manipulando
        targetButton.textContent = `Borrar Columna ${colColLetter}`;
    } else {
        console.warn(`Control button for column ${colColLetter} not found.`);
    }

    // 4. Forzar un redibujado o simplemente actualizar la interfaz si fuera necesario (aunque en este caso, solo el estado cambia)
    render();
}
