function deleteColumn() {
    if (selectedColumns.size === 0) return;

    const colsToDelete = Array.from(selectedColumns);

    // 1. Limpiar el estado para todas las celdas en estas columnas
    for (let r = 1; r <= 20; r++) {
        for (const col of colsToDelete) {
            delete estado[`${col}_${r}`];
