    // NEW: Listener para la selección de columnas en el header
    // ---------------------------------------------------------
    headerRow.addEventListener('click', function(event) {
        const target = event.target;
        if (target.classList.contains('col-header') && target.dataset.column) {
            selectColumn(target.dataset.column);
            render(); // Redibujar para aplicar/quitar la clase 'selected-column'
        }
    });

    // ---------------------------------------------------------
    // NEW: Manejo de Controles de Columna (Botones)
    // ---------------------------------------------------------
    document.getElementById('delete-col').addEventListener('click', deleteColumn);
    document.getElementById('clear-content-col').addEventListener('click', clearColumnContent);

    const colorButton = document.querySelector('.color-button');
    if (colorButton) {
        colorButton.addEventListener('click', () => {
            // Toggle visibility of the color picker menu/dropdown if implementing a complex UI, 
            // but for simplicity here, we just show an input prompt or use a predefined list.
            const colorInput = document.getElementById('color-picker');
            if (colorInput) {
                colorInput.style.display = 'block';
            } else {
                 alert("Por favor, selecciona un color de fondo del menú desplegable o ingresa el código HEX.");
            }
