// Variables de estado globales para gestionar la selección de filas y colores
let selectedRowData = { rowIndex: null, rowElement: null };
const COLUMNS_COUNT = 10; // A - J

/**
 * Asigna una clase CSS a todas las celdas de una fila dada.
 * @param {HTMLElement} rowElement El elemento TR de la fila a colorear.
 * @param {string} color El color hexadecimal o nombre del color.
 */
function applyRowColor(rowElement, color) {
    if (!rowElement || !color) return;

    const cells = rowElement.querySelectorAll('td');
    cells.forEach(cell => {
        cell.style.backgroundColor = color;
    });
}

/**
 * Resetea el color de fondo de la fila seleccionada (si existe).
 */
function resetRowColor() {
    if (selectedRowData.rowElement) {
        const cells = selectedRowData.rowElement.querySelectorAll('td');
        cells.forEach(cell => {
            cell.style.backgroundColor = '';
        });
        selectedRowData.rowElement.classList.remove('selected-row');
    }
}

/**
 * Maneja la selección de una fila al hacer clic en su número (header).
 * @param {HTMLElement} rowHeader El elemento TH con el número de fila.
 */
function handleRowSelection(rowHeader) {
    const rowIndex = parseInt(rowHeader.getAttribute('data-row-index'), 10);
    if (!rowIndex) return;

    // 1. Deseleccionar la fila actual (resetea color y estado visual)
    resetRowColor();

    // 2. Encontrar el elemento TR de la fila completa en el DOM
    const rowElement = document.querySelector(`[data-row="${rowIndex}"]`);
    if (!rowElement) return;

    // 3. Actualizar el estado global de selección
    selectedRowData.rowIndex = rowIndex;
    selectedRowData.rowElement = rowElement;

    // 4. Visualización: Marcar la fila como seleccionada (CSS) y habilitar controles
    rowHeader.classList.add('active-header');
    rowElement.classList.add('selected-row');

    document.getElementById('clear-row-btn').disabled = false;
    document.getElementById('delete-row-btn').disabled = false;
}


/**
 * Borra el contenido de todas las celdas en la fila seleccionada y actualiza el estado.
 */
function clearSelectedRow() {
    if (!selectedRowData.rowElement) return;

    const rowIndex = selectedRowData.rowIndex;
    const cells = selectedRowData.rowElement.querySelectorAll('td');

    cells.forEach(cell => {
        // Obtener la coordenada de la celda (ej: A, B...)
        const keyMatch = cell.getAttribute('data-cell').match(/\(([A-Z]+),\s*(\d+)\)/);
        if (keyMatch) {
            const col = keyMatch[1];
            // 1. Actualizar el estado a vacío
            updateCell(col, rowIndex, '');
            // 2. Limpiar contenido visible en el DOM
            cell.textContent = '';
        }
    });

    // Guardar y renderizar para asegurar que los cambios de estado se reflejen (aunque solo sea borrar)
    guardar();
    render();
}


/**
 * Elimina la fila seleccionada del DOM y limpia su contenido del estado global.
 */
function deleteSelectedRow() {
    if (!selectedRowData.rowElement) return;

    const rowIndex = selectedRowData.rowIndex;
    const rowElement = selectedRowData.rowElement;
    const cells = rowElement.querySelectorAll('td');

    // 1. Limpiar el estado de todas las celdas de esta fila
    for (let i = 0; i < COLUMNS_COUNT; i++) {
        const cell = cells[i];
        const keyMatch = cell.getAttribute('data-cell').match(/\(([A-Z]+),\s*(\d+)\)/);
        if (keyMatch) {
            const col = keyMatch[1];
            // Eliminar la clave del estado global
            delete estado[`${col}_${rowIndex}`];
        }
    }

    // 2. Remover el elemento de la fila del DOM
    rowElement.remove();

    // 3. Resetear selección y guardar/renderizar
    resetRowColor();
    selectedRowData = { rowIndex: null, rowElement: null };
    guardar();
    render();
}


/**
 * Inicializa los listeners para los controles de la fila (Delete/Clear).
 */
function initializeControlListeners() {
    document.getElementById('clear-row-btn').addEventListener('click', clearSelectedRow);
    document.getElementById('delete-row-btn').addEventListener('click', deleteSelectedRow);
}

