// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/**
 * estado almacena los contenidos de todas las celdas en formato clave_valor.
 * Clave: "COLumna_FILA" (Ej: A_1, J_20)
 * Valor: Contenido textual de la celda.
 */
let estado = {};
const CLAVE = "app";

/**
 * Carga el estado desde localStorage.
 */
function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) estado = JSON.parse(s); 
    } catch (e) {
        console.error("Error al cargar el estado:", e);
    }
}

/**
 * Guarda el estado actual en localStorage.
 */
function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    } 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el estado interno para una celda dada su coordenada y nuevo valor.
 * @param {string} col Columna (A-J)
 * @param {number} row Fila (1-20)
 * @param {string} value Nuevo contenido de la celda.
 */
function updateCell(col, row, value) {
    const key = `${col}_${row}`;
    // Solo actualizamos si el valor es diferente al que ya está guardado para evitar llamadas innecesarias a render/guard
    if (estado[key] !== String(value)) {
        estado[key] = String(value);
    }
}

/**
 * Obtiene las coordenadas de la celda activa.
 * @param {HTMLElement} element El elemento <td> que disparó el evento.
 * @returns {{col: string, row: number}|null} Objeto con columna y fila o null si no es una celda válida.
 */
function getCoordinatesFromElement(element) {
    const dataCell = element.getAttribute('data-cell');
    if (!dataCell) return null;

    // El formato en el HTML es (A, 1). Necesitamos parsearlo.
    const match = dataCell.match(/\(([^,]+),\s*(\d+)\)/);
    if (match && match[1] && match[2]) {
        return { col: match[1], row: parseInt(match[2], 10) };
    }
    return null;
}

/**
 * Selecciona una fila y actualiza el estado interno de selección.
 * @param {number} rowNumber Número de la fila a seleccionar (1-20).
 */
function selectRow(rowNumber) {
    // Limpiar selección anterior
    const oldSelectedElement = document.querySelector('.selected-row');
    if (oldSelectedElement) {
        oldSelectedElement.classList.remove('selected-row');
    }

    const rowHeaderElement = document.querySelector(`.row-header[data-row="${rowNumber}"]`);
    const rowElement = document.querySelector(`[data-row="${rowNumber}"]`);

    if (rowElement && rowHeaderElement) {
        // 1. Marcar la fila en el DOM como seleccionada
        rowElement.classList.add('selected-row');

        // 2. Actualizar estado interno de selección
        estado['selectedRow'] = parseInt(rowNumber, 10);
    } else {
        // Si no se encuentra la fila (ej: al borrarla)
        estado['selectedRow'] = null;
    }

    renderControls();
}


/**
 * Elimina completamente la fila seleccionada del estado y del DOM.
 */
function deleteSelectedRow() {
    const selectedRowNumber = estado['selectedRow'];
    if (isNaN(selectedRowNumber) || selectedRowNumber === null) {
        alert("Por favor, seleccione una fila primero.");
        return;
    }

    // 1. Confirmación de la acción destructiva
    if (!confirm(`¿Está seguro que desea borrar completamente la Fila ${selectedRowNumber}? Esta acción es irreversible.`)) {
        return;
    }

    const rowElement = document.querySelector(`[data-row="${selectedRowNumber}"]`);
    if (!rowElement) return;

    // 2. Limpiar el estado (borrar todas las claves de esta fila)
    for (let cCode = 'A'.charCodeAt(0); cCode <= 'J'.charCodeAt(0); cCode++) {
        const colLetter = String.fromCharCode(cCode);
        const key = `${colLetter}_${selectedRowNumber}`;
        delete estado[key];
    }

    // 3. Manipulación del DOM: Remover la fila completa
    rowElement.remove();

    // 4. Actualizar selección y renderizado
    estado['selectedRow'] = null;
    guardar();
    render(); // Esto también limpiará los controles y el highlighting
}


/**
 * Vacía TODO el contenido de las celdas en la fila seleccionada, manteniendo su estructura.
 */
function clearCellContentInRow() {
    const selectedRowNumber = estado['selectedRow'];
    if (isNaN(selectedRowNumber) || selectedRowNumber === null) {
        alert("Por favor, seleccione una fila primero.");
        return;
    }

    if (!confirm(`¿Está seguro que desea vaciar TODO el contenido de la Fila ${selectedRowNumber}?`)) {
