/**
 * Elimina completamente la fila seleccionada del DOM y de los datos internos (estado).
 */
function deleteSelectedRow() {
    const rowNumberToDelete = state.selectedRow;
    if (rowNumberToDelete === undefined) return;

    // 1. Recolectar todas las claves que deben ser eliminadas del estado
    const cellsToDelete = getRowCells(rowNumberToDelete);
    let keysToRemove = [];
    cellsToDelete.forEach(cell => {
        const coords = getCoordinatesFromElement(cell);
        if (coords) {
            keysToRemove.push(`${coords.col}_${coords.row}`);
        }
    });

    // 2. Eliminar las claves del estado
    keysToRemove.forEach(key => {
        delete estado[key];
    });

    // 3. Eliminar la fila completa del DOM
    const rowElement = document.querySelector(`[data-row="${rowNumberToDelete}"]`);
    if (rowElement) {
        rowElement.remove();
    }

    // 4. Actualizar estado y renderizado
    delete state.selectedRow; // Deselecciona la fila
    guardar();
    render();
}
