let selectedRow = null; // Almacena el número de la fila seleccionada (ej: 3)
const rowControls = {
    clearBtn: document.getElementById('clear-row-btn'),
    colorBtn: document.getElementById('color-row-btn'),
    deleteBtn: document.getElementById('delete-row-btn'),
    infoElement: document.getElementById('selected-row-info')
};

/**
 * Limpia la selección visual y desactiva los controles de acción.
 */
function clearRowSelection() {
    if (selectedRow) {
        // Quitar el resaltado de fila anterior
        const previousHeader = document.querySelector(`.row-header[data-row-number="${selectedRow}"]`);
        if (previousHeader) {
            previousHeader.style.backgroundColor = ''; // Restaura color default
        }
    }
    selectedRow = null;

    // Deshabilitar y resetear controles
    Object.values(rowControls).forEach(el => el.disabled = true);
    rowControls.infoElement.textContent = 'Ninguna fila seleccionada.';
}


/**
 * Maneja el clic en el encabezado de una fila para seleccionar la fila y habilitar los controles.
 * @param {Event} event El evento que disparó la acción (clic).
 */
function handleRowHeaderClick(event) {
    const target = event.target;
    // Asegurarse de que estamos en un encabezado de fila con el atributo data-row-number
    if (!target.classList.contains('row-header') || !target.dataset.rowNumber) return;

    const rowNum = parseInt(target.dataset.rowNumber, 10);

    // 1. Deseleccionar la fila actual y limpiar controles
    clearRowSelection();

    // 2. Seleccionar la nueva fila (Actualizar estado de selección visual)
    selectedRow = rowNum;
    target.style.backgroundColor = '#c3e6cb'; // Color de selección visible
    rowControls.infoElement.textContent = `Fila seleccionada: ${rowNum}. Realice acciones en esta fila.`;

    // 3. Habilitar controles y actualizar la UI
    rowControls.clearBtn.disabled = false;
    rowControls.colorBtn.disabled = false;
    rowControls.deleteBtn.disabled = false;
}


/**
 * Elimina completamente los datos de una fila del estado y el elemento DOM.
 */
function deleteSelectedRow() {
    if (!selectedRow) return;

    const rowElement = document.querySelector(`[data-row="${selectedRow}"]`);
    if (!rowElement) return;

    // 1. Eliminar todos los datos de la fila del estado 'estado'
    let keysToDelete = [];
    const cells = Array.from(rowElement.querySelectorAll('td'));
    cells.forEach((cell, index) => {
        // Columna A es índice 0, B es índice 1, etc.
        const colLetterCode = 'A'.charCodeAt(0) + index;
        const colLetter = String.fromCharCode(colLetterCode);
        keysToDelete.push(`${colLetter}_${selectedRow}`);
    });

    keysToDelete.forEach(key => {
        delete estado[key];
    });

    // 2. Eliminar la fila del DOM
    rowElement.remove();

    // 3. Guardar y Redibujar (el render() se encargará de limpiar cualquier fórmula)
    guardar();
    render();

    // 4. Resetear selección
    clearRowSelection();
}


/**
 * Limpia el contenido textual de todas las celdas en la fila seleccionada.
 */
function clearSelectedRowContent() {
    if (!selectedRow) return;

    const cells = document.querySelectorAll(`[data-row="${selectedRow}"] td`);
    let changed = false;

    cells.forEach(cell => {
        // 1. Actualizar el estado interno a vacío
        const coords = getCoordinatesFromElement(cell);
        if (coords) {
            updateCell(coords.col, coords.row, '');
            changed = true;
        }
        // 2. Limpiar el contenido visualmente
        cell.textContent = '';
    });

    if (changed) {
        guardar();
        render(); // Re-renderizar para asegurar que las fórmulas vacías se manejen correctamente
    }
}


/**
 * Cambia el color de fondo de todas las celdas en la fila seleccionada.
 * @param {string} color Código hexadecimal del color.
 */
function colorSelectedRow(color) {
    if (!selectedRow) return;

    const cells = document.querySelectorAll(`[data-row="${selectedRow}"] td`);
    let changed = false;

    cells.forEach(cell => {
        // 1. Aplicar el estilo de fondo al elemento DOM
        cell.style.backgroundColor = color;
        changed = true;
    });

    if (changed) {
        // NOTA: Dado que el color es un estilo visual y no afecta directamente los datos, 
        // solo necesitamos guardar/renderizar si hubiera algún efecto de fórmula basado en el fondo.
        // Aquí asumimos que la acción se maneja puramente por CSS/DOM.
        guardar(); // Guardamos para asegurar persistencia de estado general, aunque el color es visual.
    }
}

