```js
function conectar() {
    const spreadsheetGrid = document.getElementById('spreadsheet-grid');
    if (!spreadsheetGrid) return;

    // 1. Conectar el manejo de la selección de fila (Header Click)
    // Usamos event delegation en el contenedor padre (#spreadsheet-grid) para escuchar clics en los .row-header internos
    spreadsheetGrid.addEventListener('click', function(event) {
        const target = event.target;
        if (target && target.classList.contains('row-header')) {
            handleRowHeaderClick(event);
        }
    });

    /**
     * Maneja el cambio de contenido al perder foco (blur) o presionar Enter.
     * @param {Event} event El evento que disparó la acción (focusout/keydown).
     */
    function handleCellChange(event) {
        const target = event.target;

        // 1. Determinar coordenadas y valor
        const coords = getCoordinatesFromElement(target);
        if (!coords) return;

        let newValue = '';

        // Si es un blur o Enter, el valor está en innerText (o value si fuera input).
        if (event.type === 'blur') {
            newValue = target.textContent;
        } else if (event.type === 'keydown' && event.key === 'Enter') {
             // Capturamos el contenido actual del elemento editable.
            newValue = target.textContent; 
        }

        if (newValue !== undefined) {
            const col = coords.col;
            const row = coords.row;

            // 2. Lógica: Actualizar estado
            updateCell(col, row, newValue);

            // 3. Guardar y Renderizar
            guardar();
            render();
        }
    }

    // Escuchamos en el contenedor principal (spreadsheet-grid) para capturar eventos de los hijos contenteditable.
    spreadsheetGrid.addEventListener('blur', handleCellChange);
    spreadsheetGrid.addEventListener('keydown', function(event) {
        const target = event.target;
        if (target.hasAttribute('contenteditable') && target.textContent !== undefined) {
            // Solo procesar si se presionó Enter, que implica finalización de la edición
            if (event.key === 'Enter') {
                handleCellChange(event);
                // Prevenir el comportamiento por defecto del formulario/input al presionar enter
                event.preventDefault(); 
            }
        }
    });

    // 2. Conectar los nuevos controles de acción:
    const colorPicker = document.getElementById('color-picker');
    const colorRowBtn = document.getElementById('color-row-btn');
    const clearRowBtn = document.getElementById('clear-row-btn');
    const deleteRowBtn = document.getElementById('delete-row-btn');
    const selectAllRowsBtn = document.getElementById('select-all-rows');

    // Event Listener para el selector de color (picker)
    colorPicker.addEventListener('input', () => {
        if (selectedRow) {
            colorSelectedRow(colorPicker.value);
        }
    });

    // Event Listener para el botón de aplicar fondo
    colorRowBtn.addEventListener('click', () => {
        const color = colorPicker.value; // Usamos el valor del picker
        if (selectedRow) {
            colorSelectedRow(color);
        }
    });

    // Event Listener para vaciar contenido
    clearRowBtn.addEventListener('click', clearSelectedRowContent);

    // Event Listener para borrar fila
    deleteRowBtn.addEventListener('click', deleteSelectedRow);

    // Event Listener de selección masiva (Seleccionar todos los datos)
    selectAllRowsBtn.addEventListener('click', () => {
        if (!selectedRow) return;
        clearRowSelection(); // Limpiar cualquier selección actual antes de seleccionar todo

        const allHeaders = document.querySelectorAll('.row-header[data-row-number]');
        allHeaders.forEach(header => header.style.backgroundColor = '#c3e6cb');
        selectedRow = 'ALL'; // Cambiar estado a "ALL" para indicar selección masiva
        rowControls.infoElement.textContent = 'Todas las filas seleccionadas.';

        // Habilitar controles, pero con una lógica más compleja si se quiere manejar la acción en todo el grupo.
        // Por simplicidad, solo habilitamos los botones y dejamos que las funciones actúen sobre todos los elementos encontrados.
        Object.values(rowControls).forEach(el => el.disabled = false);

    });
}
