function conectar() {
    const spreadsheetGrid = document.getElementById('spreadsheet-grid');
    const rowHeaderContainer = document.querySelector('#spreadsheet-grid tbody');
    const selectAllButton = document.getElementById('select-all-rows');

    if (!spreadsheetGrid || !rowHeaderContainer) return;

    /**
     * Maneja el clic en los encabezados de fila (th.row-header).
     */
    function handleRowSelect(event) {
        const target = event.target;
        if (!target || !target.classList.contains('row-header')) return;
        selectRow(event);
    }

    /**
     * Maneja el cambio de contenido al perder foco (blur) o presionar Enter.
     * @param {Event} event El evento que disparó la acción (focusout/keydown).
     */
    function handleCellChange(event) {
        const target = event.target;

        // 1. Determinar coordenadas y valor
        const coords = getCoordinatesFromElement(target);
        if (!coords) return;

        let newValue = '';

        // Si es un blur o Enter, el valor está en innerText (o value si fuera input).
        if (event.type === 'blur') {
            newValue = target.textContent;
        } else if (event.type === 'keydown' && event.key === 'Enter') {
             // El evento de keydown ocurre antes del blur, pero el valor final es lo que queda en el DOM
             // Simplemente capturamos el contenido actual del elemento editable.
            newValue = target.textContent; 
        }

        if (newValue !== undefined) {
            const col = coords.col;
            const row = coords.row;

            // 2. Lógica: Actualizar estado
            updateCell(col, row, newValue);

            // 3. Guardar y Renderizar
            guardar();
            render();
        }
    }

    // --- Listeners de Controles de Fila (Nuevos) ---

    // Event Delegation para seleccionar fila haciendo clic en el encabezado
    rowHeaderContainer.addEventListener('click', handleRowSelect); 

    document.getElementById('clear-row-btn').addEventListener('click', clearSelectedRow);
    document.getElementById('color-row-btn').addEventListener('click', applyBackgroundColorToRow);
    document.getElementById('delete-row-btn').addEventListener('click', deleteSelectedRow);

