    margin-bottom: 15px;
    align-items: center;
}

button {
    padding: 8px 15px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    background-color: #007bff;
    color: white;
    transition: background-color 0.3s;
}

button:hover:not(:disabled) {
    background-color: #0056b3;
}

button:disabled {
    background-color: #ccc;
    cursor: not-allowed;
}

/* Estilos de la tabla */
#spreadsheet-grid {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

thead th {
    position: sticky;
    top: 0;
    background-color: #e9e9e9;
    text-align: center;
    padding: 10px;
    border-bottom: 2px solid #ccc;
