function toggleColumnVisibility(colLetter) {
    const allHeaders = document.querySelectorAll('.col-header[data-col-letter="' + colLetter + '"]');
    if (allHeaders.length === 0) return;

    // Determinar si está visible o no antes del cambio de clase
    let isHiddenBefore = allHeaders[0].classList.contains('hidden-col');
    const shouldHide = !isHiddenBefore;

    // Aplicar la visibilidad a todos los elementos de encabezado y celdas correspondientes
    allHeaders.forEach(header => {
        header.classList.toggle('hidden-col', shouldHide);
    });

    // Ocultar todas las celdas en el thead (ya cubierto por col-header)
    const allCells = document.querySelectorAll('#spreadsheet-grid tbody td[data-cell^="(' + colLetter + ',"]');
    allCells.forEach(cell => {
        cell.classList.toggle('hidden-col', shouldHide);
    });

    // Actualizar el estado visible para que render() lo respete
    estado['visibility_col_' + colLetter] = !shouldHide;

    updateControlState();
    render();
}
