```js
function getCoordinatesFromElement(element) {
    const cell = element;
    if (!cell || !cell.dataset.cell) return null;

    // El data-cell contiene "(Col, Row)"
    const match = cell.dataset.cell.match(/\(([^,]+),\s*(\d+)\)/);
    if (match) {
        return { col: match[1], row: parseInt(match[2], 10) };
    }
    return null;
}
