            // 2. Lógica: Actualizar estado
            updateCell(col, row, newValue);

            // 3. Guardar y Renderizar
            guardar();
            render();
        }
    }

    // --- Gestión de Eventos de Celdas ---

    // Escuchamos en el contenedor principal (spreadsheet-grid) para capturar eventos de los hijos contenteditable.
    spreadsheetGrid.addEventListener('blur', handleCellChange);
    spreadsheetGrid.addEventListener('keydown', function(event) {
        const target = event.target;
        if (target.hasAttribute('contenteditable') && target.textContent !== undefined) {
            // Solo procesar si se presionó Enter, que implica finalización de la edición
            if (event.key === 'Enter') {
                handleCellChange(event);
                // Prevenir el comportamiento por defecto del formulario/input al presionar enter
                event.preventDefault(); 
            }
        }
    });

    // --- Gestión de Eventos de Columnas y Filas (Nuevas funcionalidades) ---

    // 1. Asignar evento a los encabezados de columna (A, B, C...)
    const colHeaders = document.querySelectorAll('#spreadsheet-grid thead th[data-col]');
    colHeaders.forEach(th => {
        th.addEventListener('click', handleColumnHeaderClick);
    });

    // 2. Inicializar y conectar botones de acción en la esquina superior derecha (Columna)
    const columnLetters = Array.from(document.querySelectorAll('#spreadsheet-grid thead th[data-col]')).map(th => th.dataset.col);
    columnLetters.forEach(letter => {
        const button = document.createElement('button');
        button.textContent = `Ocultar Columna ${letter}`;
        button.classList.add('action-button', 'hide-col-btn');
        button.addEventListener('click', () => toggleColumnVisibility(letter));
        columnControlsContainer.appendChild(button);
    });

    // 3. Inicializar y conectar botones de acción para filas (Fila)
    const rowHeaders = document.querySelectorAll('.row-header');
    rowHeaders.forEach(th => {
        const rowNum = th.textContent;
        const button = document.createElement('button');
        button.textContent = `Ocultar Fila ${rowNum}`;
        button.classList.add('action-button', 'hide-row-btn');
        button.addEventListener('click', () => toggleRowVisibility(rowNum));
    });

}
