### FUNCION: hideRow
```js
function hideRow(row) {
    const rowElement = document.querySelector(`[data-row="${row}"]`);
    if (rowElement && !rowElement.classList.contains('hidden')) {
        // Ocultar toda la fila y su encabezado de índice
        rowElement.style.display = 'none';
        const header = rowElement.querySelector('.row-header');
        if (header) header.style.display = 'none';

        // Actualizar el estado para reflejar que está oculto (opcional, pero bueno para la lógica de UI)
        estado[`_visibility_${row}`] = 'hidden'; 
    } else if (!rowElement) {
         console.warn(`Fila ${row} no encontrada.`);
    }
}
```

### FUNCION: showRow
```js
function showRow(row) {
    const rowElement = document.querySelector(`[data-row="${row}"]`);
    if (rowElement && rowElement.classList.contains('hidden')) {
        // Mostrar la fila y su encabezado de índice
        rowElement.style.display = ''; // Reset to default display
        const header = rowElement.querySelector('.row-header');
        if (header) header.style.display = '';

        // Actualizar el estado
        estado[`_visibility_${row}`] = 'visible'; 
    } else if (!rowElement) {
         console.warn(`Fila ${row} no encontrada.`);
    }
}
